// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "Name", "Symbol"); }

    function testFuzz_property(uint256 initialSupply, uint256 burnAmount) public {
        vm.assume(initialSupply > 0);
        vm.assume(burnAmount > 0);
        vm.assume(burnAmount <= initialSupply);
        c = new ERCDDAToken(initialSupply, "Name", "Symbol");
        c.burn(burnAmount);
        assertTrue(c.totalSupply() == c.balanceOf(address(this)));
    }
}
